package com.bank.codeanalyzer;

import java.util.*;
import java.util.logging.*;

public class SecondUniqueDemo {
    private static final Logger log = Logger.getLogger("CodeAnalyzer");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        CodeAnalyzer analyzer = new CodeAnalyzer();
        log.info(() -> "aabcdbe → " + analyzer.secondNonRepeating("aabcdbe")); // c,d,e → 'd'
        log.info(() -> "aabb    → " + analyzer.secondNonRepeating("aabb"));    // none
    }
}

// ─── Would be in service/CodeAnalyzer.java ───
class CodeAnalyzer {
    Optional<Character> secondNonRepeating(String s) {
        Map<Character, Long> counts = s.chars()
            .mapToObj(c -> (char) c)
            .collect(java.util.stream.Collectors.groupingBy(
                ch -> ch, LinkedHashMap::new,                 // first-seen order
                java.util.stream.Collectors.counting()));
        return counts.entrySet().stream()
            .filter(e -> e.getValue() == 1L)                  // unique chars
            .map(Map.Entry::getKey)
            .skip(1)                                           // ignore the first unique
            .findFirst();                                      // → the second unique
    }
}
